<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Program Manuals</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1200px;margin:auto;padding:1rem}.cards{display:grid;gap:1rem}.card{border:1px solid #ccd3da;border-radius:10px;padding:1rem}.actions{display:flex;gap:.8rem;flex-wrap:wrap}.alert{color:#a51d2d;font-weight:700}.meter{height:.7rem;background:#ddd;border-radius:1rem;overflow:hidden}.meter span{display:block;height:100%;background:#1769d2}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main><h1>Program Manuals</h1><p>Version-controlled operational handbooks linked to program specifications.</p><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','create')):?><p><a class="btn" href="/program-manuals/create">Add program manual</a></p><?php endif;?><div class="cards"><?php foreach($rows as$row):$overdue=!empty($row['next_review_date'])&&$row['next_review_date']<date('Y-m-d');$score=(int)($row['readiness']['score']??0);?><article class="card"><h2><a href="/program-manuals/<?=(int)$row['id']?>"><?=$h($row['title'])?></a></h2><p><strong><?=$h($row['program_name'])?></strong> (<?=$h($row['program_code'])?>) · Version <?=$h($row['version_label'])?> · <?=$h($row['status'])?> · Reconciliation: <?=$h($row['reconciliation_status'])?></p><div class="meter" aria-label="Readiness <?=$score?> percent"><span style="width:<?=$score?>%"></span></div><p>Readiness: <strong><?=$score?>%</strong> · <?= (int)$row['section_count']?> sections<?php if($row['next_review_date']):?> · Review <?=$h($row['next_review_date'])?><?php endif;?></p><?php if($overdue):?><p class="alert">Manual review is overdue.</p><?php endif;?><?php if((int)$row['unresolved_count']>0):?><p class="alert"><?=(int)$row['unresolved_count']?> unresolved comparison(s).</p><?php endif;?><div class="actions"><a href="/program-manuals/<?=(int)$row['id']?>">View</a><a href="/program-manuals/<?=(int)$row['id']?>/compare">Reconcile</a><a href="/program-manuals/<?=(int)$row['id']?>/details">Detailed comparison</a><a href="/program-manuals/<?=(int)$row['id']?>/download">PDF</a><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'program_manuals','update')):?><a href="/program-manuals/<?=(int)$row['id']?>/edit">Edit</a><?php endif;?></div></article><?php endforeach;?><?php if(!$rows):?><p>No accessible program manuals found.</p><?php endif;?></div></main></body></html>
